def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos_from(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return default

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos_from(observation.get("self_position", (0, 0)))
    ox, oy = pos_from(observation.get("opponent_position", (sx, sy)))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    grid_w = observation.get("grid_width", 0) or 0
    grid_h = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)

        corners = []
        if grid_w > 0 and grid_h > 0:
            corners = [(0, 0), (0, grid_h - 1), (grid_w - 1, 0), (grid_w - 1, grid_h - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = max(corners, key=lambda c: manhattan(c, opp_pos))
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        if targets:
            best = min(targets, key=lambda p: manhattan(pos_from(p), self_pos))
            return step_toward(self_pos, pos_from(best))
        if grid_w > 0 and grid_h > 0:
            center = (grid_w // 2, grid_h // 2)
            return step_toward(self_pos, center)
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        best = min(resources, key=lambda p: manhattan(pos_from(p), self_pos))
        return step_toward(self_pos, pos_from(best))

    if grid_w > 0 and grid_h > 0:
        center = (grid_w // 2, grid_h // 2)
        return step_toward(self_pos, center)

    return step_toward(self_pos, opp_pos)

